package com.aviator.hoc.core

import java.time.LocalDate
import java.time.ZoneId
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/** Expected values were generated by running the ORIGINAL JavaScript implementation. */
class TimeCalcTest {

    @Test fun oddToTime_matchesWebApp() {
        val cases = mapOf(
            2.02 to Hms(0, 2, 2),
            1.5 to Hms(0, 1, 50),
            2.5 to Hms(0, 2, 50),
            2.75 to Hms(0, 3, 15),
            2.99 to Hms(0, 3, 39),
            150.0 to Hms(2, 29, 0),
            1437.2 to Hms(23, 57, 20),
            1.0 to Hms(0, 0, 0),
            0.5 to Hms(0, 0, 50),
            10.07 to Hms(0, 10, 7),
            61.3 to Hms(1, 1, 30),
            3.1 to Hms(0, 3, 10),
            1.45 to Hms(0, 1, 45),
        )
        cases.forEach { (odd, expected) -> assertEquals("odd $odd", expected, oddToTime(odd)) }
    }

    @Test fun parseInput_validAndInvalid() {
        assertEquals(ParsedInput(2.02, 21, 31, 22), parseInput("2.02x 21:31:22"))
        assertEquals(ParsedInput(150.0, 23, 34, 0), parseInput("150x 23:34:00"))
        assertEquals(ParsedInput(1437.2, 6, 31, 56), parseInput("1,437.20x 06:31:56"))
        assertEquals(ParsedInput(2.02, 9, 5, 7), parseInput("2.02X  9:5:7"))
        assertEquals(ParsedInput(3.1, 21, 49, 0), parseInput("  3.10x21:49:00"))
        assertNull(parseInput("abc"))
        assertNull(parseInput("2.02x 25:00:00"))
        assertNull(parseInput("0x 10:00:00"))
        assertNull(parseInput(""))
        assertNull(parseInput(null))
    }

    @Test fun windowStatus_boundaries() {
        assertEquals(WindowStatus.WAITING, windowStatus(100))
        assertEquals(WindowStatus.WAITING, windowStatus(46))
        assertEquals(WindowStatus.ACTIVE, windowStatus(45))
        assertEquals(WindowStatus.ACTIVE, windowStatus(0))
        assertEquals(WindowStatus.GRACE, windowStatus(-1))
        assertEquals(WindowStatus.GRACE, windowStatus(-45))
        assertEquals(WindowStatus.CLOSED, windowStatus(-46))
    }

    @Test fun windowTimes_wrapAroundMidnight() {
        val a = windowTimes(Hms(0, 0, 20))
        assertEquals(Hms(23, 59, 35), a.open)
        assertEquals(Hms(0, 1, 5), a.close)

        val b = windowTimes(Hms(23, 59, 30))
        assertEquals(Hms(23, 58, 45), b.open)
        assertEquals(Hms(0, 0, 15), b.close)

        val c = windowTimes(Hms(13, 57, 0))
        assertEquals(Hms(13, 56, 15), c.open)
        assertEquals(Hms(13, 57, 45), c.close)
    }

    @Test fun markWindow_isClosePlus5_andClose_minus25() {
        val target = 1_000_000_000_000L
        val close = target + WINDOW_SECONDS * 1000L
        assertFalse(isInMarkWindow(target, close - 26_000))
        assertTrue(isInMarkWindow(target, close - 25_000))
        assertTrue(isInMarkWindow(target, close + 4_999))
        assertFalse(isInMarkWindow(target, close + 5_000))
        assertTrue(isMarkWindowOver(target, close + 5_000))
        assertFalse(isMarkWindowOver(target, close + 4_000))
    }

    @Test fun countdown_floorsLikeJs() {
        assertEquals(10L, countdownSeconds(10_900, 0))
        assertEquals(-1L, countdownSeconds(0, 100))
        assertEquals(-2L, countdownSeconds(0, 1_100))
    }

    @Test fun computeSignal_crossesMidnight() {
        val zone = ZoneId.of("Asia/Colombo")
        val today = LocalDate.of(2026, 11, 26)
        // 23:59:00 + 2.02x (00:02:02) -> 00:01:02 next day
        val r = computeSignal(ParsedInput(2.02, 23, 59, 0), today, zone)
        assertEquals(Hms(0, 1, 2), r.resultTime)
        assertEquals(1, r.daysOffset)
        val expected = LocalDate.of(2026, 11, 27).atTime(0, 1, 2).atZone(zone).toInstant().toEpochMilli()
        assertEquals(expected, r.targetMs)
    }

    @Test fun formatters() {
        assertEquals("02:05", formatClock(125))
        assertEquals("1:02:05", formatClock(3725))
        assertEquals("00:00", formatClock(-4))
        assertEquals("Passed", formatCountdown(-31))
        assertEquals("5s ago", formatCountdown(-5))
        assertEquals("NOW!", formatCountdown(0))
        assertEquals("1h 2m 5s", formatCountdown(3725))
        assertEquals("2m 5s", formatCountdown(125))
        assertEquals("9s", formatCountdown(9))
    }
}
